/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _haveSpinEnd: false,
    },

    Init() {
        this._super();
    },

    setSlots(collectFreeGame) {
        let atlas = cc.vv.gameData.GetAtlasByName("base");
        for (let i = 0; i < 4; i++) {
            let bg = cc.find("bg/bg_" + (i + 1), this.node);
            let slots = collectFreeGame.slots[i];
            let active = collectFreeGame.activeCard === slots.card;
            cc.find("bg4", bg).getComponent(cc.Sprite).spriteFrame =
                atlas.getSpriteFrame(active ? "theme178_free2_bg4" : "theme178_free_bg4");
            cc.find("bg3", bg).getComponent(cc.Sprite).spriteFrame =
                atlas.getSpriteFrame(active ? "theme178_free2_bg3" : "theme178_free_bg3");
            cc.find("ear_bg", bg).getComponent(cc.Sprite).spriteFrame =
                atlas.getSpriteFrame(active ? "theme178_free2_reel_11" : "theme178_free2_reel_10");
            cc.find("bg2", bg).getComponent(cc.Sprite).spriteFrame =
                atlas.getSpriteFrame(active ? "theme178_free2_bg2" : "theme178_free_bg2");
            cc.find("your_monster", bg).active = active;
            cc.find("coin_bg/coin", bg).getComponent(cc.Label).string = slots.collectCnt;
            cc.find("win_bg/rate_bg", bg).getComponent(cc.Sprite).spriteFrame =
                atlas.getSpriteFrame(active ? "theme178_free2_bg0" : "theme178_free_bg0");
            cc.find("win_bg/rate_bg/rate", bg).getComponent(cc.Label).string = slots.mult;
            cc.find("win_bg/coin", bg).getComponent(cc.Label).string = Global.formatMoney(slots.totalWinCoin);
            cc.find("symbol", bg).color = active ? cc.Color.WHITE : cc.Color.GRAY;
        }
    },

    //创建卷轴
    createReels:function(col,row){
        this._reels = [];
        let reelCmp = this._cfg.scripts.Reels
        for (let i = 0; i < 4; i++) {
            let reels = [];
            for (let j = 0; j < col; j++) {
                let node = cc.find("reels_"+ (i + 1) + "/reel" + (j + 1), this.node)
                let scp = node.addComponent(reelCmp)
                scp.Init(j,row, cc.find("reels_" + (i + 1) + "/top_ani", this.node))
                reels.push(scp)
            }
            this._reels.push(reels);
        }

    },

    //点击旋转按钮调用
    StartMove: function () {
        this._super();
        this._haveSpinEnd = false;
        Global.SlotsSoundMgr.playNormalBgm();
    },

    OnReelBounsActionBefore:function(colIdx){

    },

    MoveReels:function(arry){
        this.moveReelLastIdx = -1
        for(let i = 0; i < arry.length; i++){
            let reels = arry[i];
            for (let j = 0; j < reels.length; j++) {
                let item = reels[j]
                item.StartMove()
                let idx = item.GetReelIdx()
                if(idx> this.moveReelLastIdx){
                    this.moveReelLastIdx = idx
                }
            }
        }
    },

    StopMove:function(){
        this._bStopRightnow = true
        this._bottomScript.ShowBtnsByState("moveing_1")

        this._stopTime = -1
        for(let i = 0; i < this._reels.length; i++ ){
            let reels = this._reels[i];
            for (let j = 0; j < reels.length; j++) {
                let item = reels[j]
                let reelStopInterv = 0 //立即停止
                item.StopMove(reelStopInterv)
                item.StopMoveRightNow()
            }
        }
    },

    async ReconnectShow() {
        let deskInfo = cc.vv.gameData.getDeskInfo();
        let rest = cc.vv.gameData.GetFreeTime()
        if (rest) {
            this.ShowGameview(true);
            if (deskInfo.collectInfo.state === 3) {
                this.setSlots(deskInfo.collectFreeGame);

                this.CanDoNextRound()
            }
        } else {
            // this.ShowGameview(false);
        }
    },

    async onMsgSpine(msg) {
        this._gameInfo = msg
        let slots = msg.collectFreeGame.slots;
        this.SetSlotsResult(slots)
    },

    SetSlotsResult: function (slots) {
        //把结果按卷轴结果整理
        for (let i = 0; i < 4; i++) {
            let cards = slots[i].resultCards;
            let acRow = cards.length / this._col
            let reelResults = []
            for(let i = 0;i < cards.length; i++){
                let row = Math.floor(i / acRow)
                let col = i % this._col
                //配置中有没有这个元素
                if(this._cfg.symbol[cards[i]]){
                    let res = {}
                    res.sid = cards[i] //符号id
                    if(!reelResults[col]) reelResults[col] = []
                    reelResults[col].unshift(res)
                }

            }

            let reels = this._reels[i];
            for(let i = 0; i < reels.length; i++){
                let item = reels[i]
                let reelRes = reelResults[i]
                item.SetResult(reelRes)
            }
        }
    },

    //显示中奖路线
    //竞品中的显示线路是：先总，后单条循环。目前我们只显示总的
    ShowWinTrace:function(){
        for (let i = 0; i < 4; i++) {
            let zjLuXian = this._gameInfo.collectFreeGame.slots[i].zjLuXian;

            let allWinIdx = []

            //中奖位置
            for(let j = 0; j < zjLuXian.length; j++){
                let item = zjLuXian[j]
                for(let idx = 0; idx < item.indexs.length; idx++){
                    allWinIdx[item.indexs[idx]] = 1
                }
            }

            //总
            for (const key in allWinIdx) {
                let symbol = this.GetSymbolByIdx(Number(key), i)
                if(symbol){
                    symbol.playWinAnimation()
                    symbol.ShowKuang()
                }
            }
        }

    },

    GetSymbolByIdx:function(idx, reelIndex){
        let col = (idx - 1) % this._col
        let row = this._row - Math.floor((idx -1)/this._col) -1
        return this._reels[reelIndex][col].GetSymbolByRow(row)
    },

    //重写：显示bonus中奖
    async OnSpinEnd() {
        if (this._haveSpinEnd) {
            return;
        }
        this._haveSpinEnd = true;
        await this.collectCoin();

        this.ShowWinTrace();

        for (let i = 0; i < 4; i++) {
            let winCoin = this._gameInfo.collectFreeGame.slots[i].winCoin;
            let totalWinCoin = this._gameInfo.collectFreeGame.slots[i].totalWinCoin;
            Global.doRoallNumEff(
                cc.find("bg/bg_" + (i + 1) + "/win_bg/coin", this.node),
                totalWinCoin - winCoin,
                totalWinCoin,
                2,
                null,
                null,
                0,
                true,
                false
            )
        }

        await cc.vv.gameData.awaitTime(2.5);

        if (this._gameInfo.collectFreeGame.isEnd) {
            await this.popFreeResultDialog();

            this._haveSpinEnd = false;

            this.cutScene();

            await cc.vv.gameData.awaitTime(2);

            cc.find("slots", this.node.parent).active = true;
            this.node.active = false;
            cc.vv.gameData.SetSlotsScript(cc.find("slots", this.node.parent).getComponent("FatherOfInvention_Slots"));

            await cc.vv.gameData.awaitTime(1);

            cc.find("slots", this.node.parent).getComponent("FatherOfInvention_Slots").ShowBottomWin(this._gameInfo.collectFreeGame.winCoin, this._gameInfo.collectFreeGame.winCoin, true, () => {
                Global.SlotsSoundMgr.stopBgm();
                Global.SlotsSoundMgr.playNormalBgm();
                this._bottomScript.SetBetNodeVisible(true);
                cc.find("slots", this.node.parent).getComponent("FatherOfInvention_Slots").ShowGameview(false);
                cc.find("slots", this.node.parent).getComponent("FatherOfInvention_Slots").CanDoNextRound();
            });
        } else {
            this.CanDoNextRound();
        }
    },

    cutScene() {
        cc.vv.AudioManager.playEff("games/FatherOfInvention/", "transition2", true);
        let transition = cc.find("transition2", this.node.parent);
        transition.active = true;
        transition.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        transition.getComponent(sp.Skeleton).setCompleteListener(()=>{
            transition.getComponent(sp.Skeleton).setCompleteListener(null);
            transition.active = false;
        });
    },

    popFreeResultDialog() {
        return new Promise(async (success) => {
            cc.vv.AudioManager.playEff("games/FatherOfInvention/", "free_dialog_collect_show", true);

            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;

            let free_bg = cc.find("free_dialog_bg", free_dialog);
            free_bg.opacity = 0;
            free_bg.runAction(cc.fadeTo(0.2, 200));

            let dialog = cc.find("result_node", free_dialog);
            dialog.opacity = 255;
            dialog.active = true;

            let spine = cc.find("spine", dialog).getComponent(sp.Skeleton);
            spine.node.active = true;

            let coin_bg = cc.find("coin_bg", dialog);
            coin_bg.scale = 0;

            let coin = cc.find("coin", dialog);
            coin.scale = 0;
            coin.getComponent(cc.Label).string = "";

            spine.setAnimation(0, "animation1", false);
            spine.addAnimation(0, "animation2", true);

            let btn_collect = cc.find("btn_collect", dialog);
            btn_collect.scale = 0;

            await cc.vv.gameData.awaitTime(0.3);

            Global.doRoallNumEff(coin, 0, this._gameInfo.collectFreeGame.winCoin, 3, null, null, 0, true);
            cc.tween(coin)
                .to(0.2, {scale: 1})
                .start();

            cc.tween(coin_bg)
                .to(0.2, {scale: 1})
                .start();

            await cc.vv.gameData.awaitTime(0.2);

            cc.tween(btn_collect)
                .to(0.2, {scale: 1})
                .start();

            btn_collect.off("click");

            await cc.vv.gameData.awaitTime(0.2);

            let func = async ()=>{
                btn_collect.off("click");
                cc.vv.AudioManager.playEff("games/FatherOfInvention/", "btn_click", true);
                // cc.vv.AudioManager.playEff("games/SpookyHalloween/", "free_dialog_collect_close", true);
                cc.tween(dialog)
                    .to(0.2, {opacity: 0})
                    .start();

                cc.tween(free_bg)
                    .to(0.2, {opacity: 0})
                    .start();

                await cc.vv.gameData.awaitTime(0.3);

                dialog.active = false;
                free_dialog.active = false;
                spine.node.active = false;
                success();
            }

            cc.vv.gameData.checkAutoPlay(btn_collect, func);

            btn_collect.on("click", async () => {
                btn_collect.stopAllActions();
                await func();
            });
        })
    },

    async collectCoin() {
        let slots = this._gameInfo.collectFreeGame.slots;
        for (let i = 0; i < slots.length; i++) {
            let collectIdxs = slots[i].currCollectIdxs;
            let preCollectCnt = slots[i].collectCnt - slots[i].currCollectIdxs.length;
            for (let j = 0; j < collectIdxs.length; j++) {
                let symbol = this.GetSymbolByIdx(collectIdxs[j], i);
                if (symbol) {
                    symbol.playStopAnimation();
                    cc.vv.AudioManager.playEff("games/FatherOfInvention/", "collect_count", true);
                    preCollectCnt++;
                    cc.find("bg/bg_" + (i + 1) + "/coin_bg/coin", this.node).getComponent(cc.Label).string = preCollectCnt;
                    await cc.vv.gameData.awaitTime(0.5);
                }
            }
        }
    },

    update (dt) {
        if(this._stopTime > 0){
            this._stopTime = this._stopTime - dt
            if(this._stopTime <= 0 ){ //空转时间到了
                if(this.CanStopSlot()){//满足开始停止的条件
                    this._bottomScript.ShowBtnsByState("moveing_2")
                    //倒计时完，设置一次
                    for(let i = 0; i < this._reels.length; i++ ){
                        let reels = this._reels[i];
                        for (let j = 0; j < reels.length; j++) {
                            let item = reels[j]
                            let reelStopInterv = this.GetReelStopInter(j)
                            item.StopMove(reelStopInterv)
                        }
                    }
                }
                else{
                    //如果没有结果,则延迟一帧
                    this._stopTime = dt

                    //记录一个超时时间.
                    this._roundSpineTime = this._roundSpineTime || 0
                    this._roundSpineTime += dt
                    if(this._roundSpineTime > 30 ){
                        // this._stopTime = -1
                        this._topScript.SetBackLobby(true)
                    }
                }
            }
        }
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview: function (bFree) {
        if(bFree){
            if (cc.vv.gameData.getDeskInfo().collectInfo.state === 3) {
                let total = cc.vv.gameData.GetTotalFree()
                let rest = cc.vv.gameData.GetFreeTime()

                //显示免费次数
                this._bottomScript.ShowFreeModel(true,total-rest,total)
                let nTotal = cc.vv.gameData.GetTotalFreeWin()
                this._bottomScript.SetWin(nTotal)
                this._bottomScript.SetBetNodeVisible(false);
            }
        }
        else{
            this._bottomScript.SetBetNodeVisible(true);
            this._bottomScript.ShowFreeModel(false)
        }
    },

});