/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    //旋转
    StartMove:function(){
        this._super();
    },

    //列停止
    OnReelSpinEnd:function(){
        this._super();
    },

    playReelStop(){
        this._super();

        if (this._originResult) {
            for(let i = 0; i < this._originResult.length; i++){
                let item = this._symbols[i]
                if (item.GetShowId() === this._cfg.ballId) {
                    // cc.vv.AudioManager.playEff("games/FatherOfInvention/", "symbol_bonus_drop", true);
                    item.playStopAnimation();
                }
                
                if (item.GetShowId() === this._cfg.collectSymbolId) {
                    item.playStopAnimation();
                    cc.vv.AudioManager.playEff("games/FatherOfInvention/", "symbol_coins_drop", true);
                }
            }
        }
    },

    //reel变化尺寸的时候，需要设置高度的节点(y锚点都是0，这样设置长度都是y方向)
    //reel/mask ,
    //reels_bg/bg*,
    GetResizeHeightObjs:function(){
        let objs = []
        let mask = cc.find("mask",this.node)
        if(mask){
            objs.push(mask)
        }

        let bg = cc.find("reels_bg/reel_bg"+(this._reelIdx+1),this.node.parent.parent)
        if(bg){
            objs.push(bg)
        }

        if (this._reelIdx === 0) {
            for (let i = 1; i < 5; i++) {
                let line = cc.find("reels_frame/line_" + i, this.node.parent.parent);
                if (line) {
                    objs.push(line);
                }
            }

            let left_bg = cc.find("reels_frame/left_bg", this.node.parent.parent);
            if (left_bg) {
                objs.push(left_bg);
            }

            let right_bg = cc.find("reels_frame/right_bg", this.node.parent.parent);
            if (right_bg) {
                objs.push(right_bg);
            }

            let black_bg = cc.find("black_bg", this.node.parent.parent);
            if (black_bg) {
                objs.push(black_bg);
            }
        }

        return objs
    },

    //reel变化尺寸的时候，需要移动的节点
    //reels_frame/reel*/frame
    GetResizeMoveingObjs:function(){
        let objs = []

        if (this._reelIdx === 0) {
            let frameTop = cc.find("reels_frame/top_bg",this.node.parent.parent)
            if(frameTop){
                objs.push(frameTop)
            }

            let left_top = cc.find("reels_frame/left_top",this.node.parent.parent)
            if(left_top){
                objs.push(left_top)
            }

            let right_top = cc.find("reels_frame/right_top",this.node.parent.parent)
            if(right_top){
                objs.push(right_top)
            }

            let collect_node = cc.find("collect_node",this.node.parent.parent)
            if(collect_node){
                objs.push(collect_node)
            }

            let tower = cc.find("collect_tower",this.node.parent.parent)
            if(tower){
                objs.push(tower)
            }
        }

        return objs
    },
});