/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        wheel: cc.Node,
        spine_zhuanpan: sp.Skeleton,
        spine_chilun: sp.Skeleton,
        spine_huoxing: sp.Skeleton,
        spine_zhongjiang: sp.Skeleton,
        free_times: cc.Label,
        touch_spin: cc.Node,
        average_bet: cc.Label,

        _successCallback: null,
    },

    async startWheel(collectInfo) {
        // return new Promise((success)=>{
        //     this._successCallback = success;
            this.node.y = cc.winSize.height;
            this.node.active = true;

            cc.tween(this.node)
                .to(0.5, {y: 0})
                .start();

            this.wheel.angle = 0;

            this.spine_zhuanpan.node.active = true;

            this.spine_chilun.node.active = true;
            this.spine_chilun.node.color = cc.Color.WHITE;
            this.spine_chilun.setAnimation(0, "animation", true);

            this.spine_huoxing.node.active = false;

            this.spine_zhongjiang.node.active = false;

            this.touch_spin.off(cc.Node.EventType.TOUCH_END);

            let func = ()=>{
                this.touch_spin.off(cc.Node.EventType.TOUCH_END);
                cc.vv.AudioManager.playEff("games/FatherOfInvention/", "collect_roulette_spin", true);

                let req = {c: MsgId.SLOT_SUBGAME_DATA};
                req.uid = Global.playerData.uid;
                req.gameid = cc.vv.gameData._gameId;
                req.data = {};
                req.data.rtype = 3;
                cc.vv.NetManager.send(req);
            }
            cc.vv.gameData.checkAutoPlay(this.touch_spin, func);

            this.touch_spin.on(cc.Node.EventType.TOUCH_END, ()=>{
                this.touch_spin.stopAllActions();
                func();
            });

            this.free_times.string = collectInfo.currFreeCnt;

            this.average_bet.string = Global.formatNumShort(collectInfo.startPrice, 0);

            for (let i = 0; i < collectInfo.monsterInfo.length; i++) {
                let info = collectInfo.monsterInfo[i];
                cc.find("multiplier_" + (i + 1), this.wheel).getComponent(cc.Label).string = "X" + info.currmult;
            }



        // });
    },

    async onRcvSubgameData(msg) {
        cc.vv.gameData.getDeskInfo().collectInfo = msg.data.collectInfo;

        this.spine_zhuanpan.node.active = false;

        this.spine_chilun.setAnimation(0, "animation2", true);
        this.spine_chilun.node.color = cc.Color.GRAY;

        this.spine_huoxing.node.active = true;

        let index = [6, 5, 8, 7];
        await this._rotateWheel(index.indexOf(msg.data.collectFreeGame.activeCard));
        cc.vv.AudioManager.playEff("games/FatherOfInvention/", "collect_roulette_stop", true);

        this.spine_zhongjiang.node.active = true;

        await cc.vv.gameData.awaitTime(2);

        this.cutScene();

        await cc.vv.gameData.awaitTime(2);

        this.node.active = false;
        cc.find("slots", this.node.parent).active = false;
        cc.find("super_slots", this.node.parent).active = true;
        cc.vv.gameData.SetSlotsScript(cc.find("super_slots", this.node.parent).getComponent("FatherOfInvention_SuperSlots"));
        cc.find("super_slots", this.node.parent).getComponent("FatherOfInvention_SuperSlots").setSlots(msg.data.collectFreeGame);
        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playBgm("mapfree_bgm");

        cc.vv.gameData.SetTotalFree(msg.data.collectFreeGame.freeCnt);
        cc.vv.gameData.SetFreeTime(msg.data.collectFreeGame.freeCnt);

        await cc.vv.gameData.awaitTime(2);

        cc.vv.gameData.GetSlotsScript().CanDoNextRound();
    },

    cutScene() {
        cc.vv.AudioManager.playEff("games/FatherOfInvention/", "transition2", true);
        let transition = cc.find("transition2", this.node.parent);
        transition.active = true;
        transition.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        transition.getComponent(sp.Skeleton).setCompleteListener(()=>{
           transition.getComponent(sp.Skeleton).setCompleteListener(null);
           transition.active = false;
        });
    },

    async _rotateWheel(endIndex) {
        return new Promise((success)=>{
            let angle = endIndex * 90 - 2160;
            cc.log(angle);
            cc.vv.AudioManager.playEff("games/FatherOfInvention/", "collect_roulette_start", true);
            let action = cc.rotateBy(6, angle).easing(cc.easeSineInOut());
            this.wheel.runAction(cc.sequence(action, cc.callFunc(()=>{
                // cc.vv.AudioManager.playEff("games/MammothGrand/", "wheel_end", true);
                success();
            })));
        });
    },
});