/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    Init:function(idx,node){
        this._super(idx, node);
    },

    //显示随机符号
    ShowRandomSymbol:function(){
        this._super();
        if (this._id === cc.vv.gameData.getGameCfg().ballId) {
            this.node.zIndex = 400;
            cc.vv.AudioManager.playEff("games/FatherOfInvention/", "symbol_bonus_slip", true);
        }
    },

    StopMoveBefore(){

    },

    StartMove: function () {
        this._super();
        let cfg = cc.vv.gameData.getGameCfg();
        if (this._id === cfg.scatterId) {
            this.node.zIndex = 500;
        }

        if (this._id === cfg.ballId) {
            this.node.zIndex = 400;
        }
    },

    //设置_symbolIdx 行序号
    SetSymbolIdx:function(idx){
        this._super(idx);
        let cfg = cc.vv.gameData.getGameCfg();

        if (this._id === cfg.scatterId) {
            this.node.zIndex = 500;
        }

        if (this._id === cfg.ballId) {
            this.node.zIndex = 400;
        }
    },
});