/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        btn_tip: cc.Node,
        title_freeTimes: cc.Label,
        optionNodes: [cc.Node],
        btn_chooseRandom: cc.Node,
        btn_startFreeSpin: cc.Node,
        btn_back: cc.Node,
        black_bg: cc.Node,
        energize_node: cc.Node,
        energize_icon: cc.Sprite,
        energize_btn_yes: cc.Node,
        energize_btn_no: cc.Node,
        start_node: cc.Node,
        start_curFreeTime: cc.Label,
        start_btn_no: cc.Node,
        start_btn_start: cc.Node,
        help_node: cc.Node,
        help_bg: cc.Node,
        help_content: cc.Node,
        help_title: cc.Node,
        btn_i_see: cc.Node,

        _successCallback: null,

        _canSelect: false,

        _curSelectCard: 0,
    },

    onLoad() {

    },

    initMap(collectInfo) {
        let monsterInfo = collectInfo.monsterInfo;
        this.node.active = true;
        this.node.y = cc.winSize.height;
        let cfg = cc.vv.gameData.getGameCfg();

        this.btn_tip.off("click");
        this.btn_tip.on("click", ()=>{
            cc.vv.AudioManager.playEff("games/FatherOfInvention/", "btn_click", true);

            this.black_bg.active = true;
            this.black_bg.opacity = 200;
            this.help_node.active = true;
            this.help_bg.scale = 0;
            this.help_bg.opacity = 255;
            this.help_content.scale = 0;
            this.help_content.opacity = 255;
            this.help_title.scale = 0;
            this.help_title.opacity = 255;
            this.btn_i_see.scale = 0;
            this.btn_i_see.opacity = 255;
            this.btn_i_see.getComponent(cc.Button).interactable = true;

            cc.tween(this.help_bg)
                .to(0.2, {scale: 1.25}, {easing: "backOut"})
                .start();

            cc.tween(this.help_title)
                .delay(0.2)
                .to(0.2, {scale: 1}, {easing: "backOut"})
                .start();

            cc.tween(this.help_content)
                .delay(0.4)
                .to(0.2, {scale: 1}, {easing: "backOut"})
                .start();

            cc.tween(this.btn_i_see)
                .delay(0.6)
                .to(0.2, {scale: 1}, {easing: "backOut"})
                .start();
        });

        this.title_freeTimes.string = collectInfo.currFreeCnt;

        for (let i = 0; i < monsterInfo.length; i++) {
            let info = monsterInfo[i];
            let node = this.optionNodes[i];
            cc.find("total_multiplier", node).getComponent(cc.Label).string = "X" + info.triggerMult[info.triggerMult.length - 1];
            cc.find("cur_multiplier", node).getComponent(cc.Label).string = "X" + info.currmult;
            for (let j = 0; j < info.maxLen; j++) {
                cc.find("progress_" + (j + 1), node).active = j < info.currLen;
            }
            for (let j = 0; j < 3; j++) {
                cc.find("target_" + (j + 1), node).color = info.currLen < info.triggerIdx[j] ? cc.Color.WHITE : cc.Color.GRAY;
            }
            cc.find("idle_spine", node).active = info.currLen < info.maxLen;

            cc.find("add_spins", node).color = info.currLen === info.maxLen ? cc.Color.GRAY : cc.Color.WHITE;

            node.on(cc.Node.EventType.TOUCH_END, ()=>{
                // node.off(cc.Node.EventType.TOUCH_END);
                if (!this._canSelect) {
                    return;
                }
                cc.vv.AudioManager.playEff("games/FatherOfInvention/", "collect_monster_click", true);

                if (info.currLen >= info.maxLen) {
                    return;
                }

                this._curSelectCard = info.card;

                this.black_bg.active = true;
                this.black_bg.opacity = 200;

                this.energize_node.active = true;
                this.energize_node.opacity = 255;
                this.energize_node.scale = 0;
                cc.tween(this.energize_node)
                    .to(0.2, {scale: 1}, {easing: "backOut"})
                    .start();

                // let atlas = cc.vv.gameData.GetAtlasByName("symbol");
                this.energize_icon.node.getComponent("ImgSwitchCmp").setIndex(info.card - 5);

                this.energize_btn_yes.on("click", ()=>{
                    cc.vv.AudioManager.playEff("games/FatherOfInvention/", "btn_click", true);
                    this.energize_btn_yes.off("click");

                    cc.tween(this.energize_node)
                        .to(0.2, {opacity: 0})
                        .call(()=>{
                            this.energize_node.active = false;
                        })
                        .start();

                    this.btn_chooseRandom.getComponent(cc.Button).interactable = false;

                    this.btn_startFreeSpin.getComponent(cc.Button).interactable = false;

                    for (let optionNode of this.optionNodes) {
                        cc.find("idle_spine", optionNode).active = false;
                        optionNode.off(cc.Node.EventType.TOUCH_END);
                    }

                    this._canSelect = false;

                    let req = {c: MsgId.SLOT_SUBGAME_DATA};
                    req.uid = Global.playerData.uid;
                    req.gameid = cc.vv.gameData._gameId;
                    req.data = {};
                    req.data.rtype = 1;
                    req.data.choiceId = this._curSelectCard;
                    cc.vv.NetManager.send(req);
                });

                this.energize_btn_no.on("click", ()=>{
                    cc.vv.AudioManager.playEff("games/FatherOfInvention/", "btn_click", true);
                    this.energize_btn_no.off("click");

                    cc.tween(this.energize_node)
                        .to(0.2, {opacity: 0})
                        .call(()=>{
                            this.energize_node.active = false;
                        })
                        .start();

                    cc.tween(this.black_bg)
                        .to(0.2, {opacity: 0})
                        .call(()=>{
                            this.black_bg.active = false;
                        })
                        .start();
                });
            });
        }

        let canChooseRandom = false;
        for (let monsterInfoElement of monsterInfo) {
            if (monsterInfoElement.currLen !== monsterInfoElement.maxLen) {
                canChooseRandom = true;
                break;
            }
        }
        if (collectInfo.currFreeCnt === 22) {
            canChooseRandom = false;
        }
        this.btn_chooseRandom.getComponent(cc.Button).interactable = canChooseRandom;

        this.btn_chooseRandom.off("click");
        this.btn_chooseRandom.on("click", ()=>{
            cc.vv.AudioManager.playEff("games/FatherOfInvention/", "btn_click", true);
            this.black_bg.active = true;
            this.black_bg.opacity = 200;

            this.energize_node.active = true;
            this.energize_node.opacity = 255;
            this.energize_node.scale = 0;
            cc.tween(this.energize_node)
                .to(0.2, {scale: 1}, {easing: "backOut"})
                .start();

            let randomCard = this.getCanSelectRandomCard(collectInfo);
            let atlas = cc.vv.gameData.GetAtlasByName("symbol");
            this.energize_icon.node.getComponent("ImgSwitchCmp").setIndex(randomCard - 5);

            this._curSelectCard = randomCard;

            this.energize_btn_yes.on("click", ()=>{
                cc.vv.AudioManager.playEff("games/FatherOfInvention/", "btn_click", true);
                this.energize_btn_yes.off("click");

                for (let optionNode of this.optionNodes) {
                    cc.find("idle_spine", optionNode).active = false;
                    optionNode.off(cc.Node.EventType.TOUCH_END);
                }

                this.btn_chooseRandom.getComponent(cc.Button).interactable = false;

                this.btn_startFreeSpin.getComponent(cc.Button).interactable = false;

                this._canSelect = false;

                cc.tween(this.energize_node)
                    .to(0.2, {opacity: 0})
                    .call(()=>{
                        this.energize_node.active = false;
                    })
                    .start();

                let req = {c: MsgId.SLOT_SUBGAME_DATA};
                req.uid = Global.playerData.uid;
                req.gameid = cc.vv.gameData._gameId;
                req.data = {};
                req.data.rtype = 1;
                req.data.choiceId = this._curSelectCard;
                cc.vv.NetManager.send(req);
            });

            this.energize_btn_no.on("click", ()=>{
                cc.vv.AudioManager.playEff("games/FatherOfInvention/", "btn_click", true);
                this.energize_btn_no.off("click");

                cc.tween(this.energize_node)
                    .to(0.2, {opacity: 0})
                    .call(()=>{
                        this.energize_node.active = false;
                    })
                    .start();

                cc.tween(this.black_bg)
                    .to(0.2, {opacity: 0})
                    .call(()=>{
                        this.black_bg.active = false;
                    })
                    .start();
            });
        });

        this.btn_startFreeSpin.getComponent(cc.Button).interactable = collectInfo.currFreeCnt > 0;
        this.btn_startFreeSpin.off("click");
        this.btn_startFreeSpin.on("click", ()=>{
            cc.vv.AudioManager.playEff("games/FatherOfInvention/", "btn_click", true);
            this.black_bg.active = true;
            this.black_bg.opacity = 200;

            this.start_node.active = true;
            this.start_node.opacity = 255;
            this.start_node.scale = 0;
            cc.tween(this.start_node)
                .to(0.2, {scale: 1}, {easing: "backOut"})
                .start();

            this.start_curFreeTime.string = collectInfo.currFreeCnt;

            this.start_btn_start.on("click", ()=>{
                cc.vv.AudioManager.playEff("games/FatherOfInvention/", "btn_click", true);
                this.start_btn_start.off("click");

                this._canSelect = false;

                this.btn_chooseRandom.getComponent(cc.Button).interactable = false;
                this.btn_startFreeSpin.getComponent(cc.Button).interactable = false;

                cc.tween(this.black_bg)
                    .to(0.2, {opacity: 0})
                    .call(()=>{
                        this.black_bg.active = false;
                    })
                    .start();

                cc.tween(this.start_node)
                    .to(0.2, {opacity: 0})
                    .call(()=>{
                        this.start_node.active = false;
                    })
                    .start();

                let req = {c: MsgId.SLOT_SUBGAME_DATA};
                req.uid = Global.playerData.uid;
                req.gameid = cc.vv.gameData._gameId;
                req.data = {};
                req.data.rtype = 2;
                cc.vv.NetManager.send(req);
            });

            this.start_btn_no.on("click", ()=>{
                cc.vv.AudioManager.playEff("games/FatherOfInvention/", "btn_click", true);
                this.start_btn_no.off("click");

                cc.tween(this.black_bg)
                    .to(0.2, {opacity: 0})
                    .call(()=>{
                        this.black_bg.active = false;
                    })
                    .start();

                cc.tween(this.start_node)
                    .to(0.2, {opacity: 0})
                    .call(()=>{
                        this.start_node.active = false;
                    })
                    .start();
            });
        });

        this.btn_i_see.off("click");
        this.btn_i_see.on("click", ()=>{
            cc.vv.AudioManager.playEff("games/FatherOfInvention/", "btn_click", true);
            this.btn_i_see.getComponent(cc.Button).interactable = false;

            cc.tween(this.black_bg)
                .to(0.2, {opacity: 0})
                .delay(0.1)
                .call(()=>{
                    this.black_bg.active = false;
                    this.help_node.active = false;
                })
                .start();

            cc.tween(this.help_bg)
                .to(0.2, {opacity: 0})
                .start();

            cc.tween(this.help_content)
                .to(0.2, {opacity: 0})
                .start();

            cc.tween(this.help_title)
                .to(0.2, {opacity: 0})
                .start();

            cc.tween(this.btn_i_see)
                .to(0.2, {opacity: 0})
                .start();
        });
    },

    getCanSelectRandomCard(collectInfo) {
        let array = [];
        for (let monsterInfo of collectInfo.monsterInfo) {
            if (monsterInfo.currLen < monsterInfo.maxLen) {
                array.push(monsterInfo);
            }
        }
        return array[Math.floor(Math.random() * array.length)].card;
    },

    openMap(showBtn) {
        this.node.y = cc.winSize.height;
        this.node.active = true;

        if (showBtn) {
            for (let optionNode of this.optionNodes) {
                cc.find("idle_spine", optionNode).active = false;
            }

            this.btn_chooseRandom.getComponent(cc.Button).interactable = false;

            this.btn_startFreeSpin.getComponent(cc.Button).interactable = false;
        } else {
            this.btn_back.active = false;
        }
        // cc.vv.AudioManager.playEff("games/SpookyHalloween/", "map_open", true);
        cc.tween(this.node)
            .to(0.5, {y : 0})
            .start();
        if (showBtn) {
            this.btn_back.active = true;
            this.btn_back.scale = 0;
            cc.tween(this.btn_back)
                .delay(0.6)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            this.btn_back.on("click", ()=>{
                cc.vv.AudioManager.playEff("games/FatherOfInvention/", "btn_click", true);
                this.btn_back.off("click");
                // cc.vv.AudioManager.playEff("games/SpookyHalloween/", "map_close", true);
                cc.tween(this.btn_back)
                    .to(0.2, {scale: 0})
                    .start();

                cc.tween(this.node)
                    .to(0.5, {y : cc.winSize.height})
                    .call(()=>{
                        cc.vv.gameData.GetSlotsScript().CanDoNextRound();
                        this.node.active = false;
                    })
                    .start();
            });
        }
    },

    async showMap(collectInfo) {
        // return new Promise((success)=>{
        //     this._successCallback = success;
        //
        //     // this.node.active = true;
        //     let cfg = cc.vv.gameData.getGameCfg();

            this.initMap(collectInfo);

            this.openMap(false);

            await cc.vv.gameData.awaitTime(1);

            this._canSelect = true;

            cc.vv.gameData.GetSlotsScript().clearCollectProgress();
        // });
    },

    async onRcvSubGameData(msg) {
        if (msg.code !== 200) {
            return;
        }

        if (msg.data.rtype === 1) {
            this.black_bg.active = false;

            let collectInfo = msg.data.collectInfo;
            cc.vv.gameData.getDeskInfo().collectInfo = collectInfo;
            let monsterInfo = collectInfo.monsterInfo;
            let node = this.optionNodes[msg.data.choiceId - 5];
            let select_spine = cc.find("select_spine", node).getComponent(sp.Skeleton);
            select_spine.node.active = true;
            select_spine.setAnimation(0, "animation", false);
            select_spine.setCompleteListener(()=>{
                select_spine.setCompleteListener(null);
                select_spine.node.active = false;
            })
            cc.vv.AudioManager.playEff("games/FatherOfInvention/", "collect_monster_rise", true);

            await cc.vv.gameData.awaitTime(1);

            let spine = cc.find("spine", node).getComponent(sp.Skeleton);
            spine.setAnimation(0, "animation2", false);
            spine.addAnimation(0, "animation3", true);

            await cc.vv.gameData.awaitTime(1);

            let info = monsterInfo[msg.data.choiceId - 5];
            let progress = cc.find("progress_" + info.currLen, node);
            progress.active = true;
            progress.scaleX = 0;
            cc.tween(progress)
                .to(0.5, {scaleX: 1})
                .start();
            
            if (info.triggerIdx.indexOf(info.currLen) !== -1) {
                // 触发了更新倍数
                await cc.vv.gameData.awaitTime(0.5);
                cc.vv.AudioManager.playEff("games/FatherOfInvention/", "collect_times_accept", true);
                let target = cc.find("target_" + (info.triggerIdx.indexOf(info.currLen) + 1), node);
                let sprite = cc.instantiate(target);
                target.color = cc.Color.GRAY;
                sprite.parent = target.parent;
                sprite.position = target.position;

                cc.tween(sprite)
                    .to(0.2, {scale: 1.2})
                    .delay(0.3)
                    .then(cc.jumpTo(0.5, cc.find("cur_multiplier", node).position, 50, 1))
                    .call(()=>{
                        cc.find("cur_multiplier", node).getComponent(cc.Label).string = "X" + info.currmult;
                    })
                    .removeSelf()
                    .start();

                await cc.vv.gameData.awaitTime(1);
            }
            
            if (info.currLen === info.maxLen) {
                // 一条收集满了
                await cc.vv.gameData.awaitTime(0.5);

                cc.vv.AudioManager.playEff("games/FatherOfInvention/", "collect_times_fly", true);
                let finish_spine = cc.find("finish_spine", node).getComponent(sp.Skeleton);
                let animationName = "animation1";
                if (msg.data.choiceId === 7) {
                    animationName = "animation2";
                } else if (msg.data.choiceId === 8) {
                    animationName = "animation3";
                }
                finish_spine.node.active = true;
                finish_spine.setAnimation(0, animationName, false);
                finish_spine.setCompleteListener(()=>{
                    finish_spine.setCompleteListener(null);
                    finish_spine.node.active = false;
                });

                await cc.vv.gameData.awaitTime(0.5);

                let spin_sprite = cc.find("add_spins", node);
                let copy_spin = cc.instantiate(spin_sprite);
                copy_spin.parent = spin_sprite.parent;
                copy_spin.position = spin_sprite.position;
                let endPos = this.title_freeTimes.node.convertToWorldSpaceAR(cc.v2(0, 0));
                endPos = node.convertToNodeSpaceAR(endPos);
                cc.tween(copy_spin)
                    .to(0.2, {scale: 1.2})
                    .delay(0.3)
                    .to(0.5, {position: endPos})
                    .call(()=>{
                        this.title_freeTimes.string = collectInfo.currFreeCnt;
                    })
                    .removeSelf()
                    .start();

                await cc.vv.gameData.awaitTime(1.5);
            }

            await cc.vv.gameData.awaitTime(1);

            cc.tween(this.node)
                .to(0.5, {y: cc.winSize.height})
                .start();

            await cc.vv.gameData.awaitTime(0.5);

            this.node.active = false;
            cc.vv.gameData.GetSlotsScript().CanDoNextRound();
            // this._successCallback();
        } else if (msg.data.rtype === 2) {
            // 进入免费游戏
            cc.vv.gameData.getDeskInfo().collectInfo = msg.data.collectInfo;
            await cc.vv.gameData.awaitTime(0.5);
            cc.find("wheel", this.node.parent).getComponent("FatherOfInvention_Wheel").startWheel(msg.data.collectInfo);

            await cc.vv.gameData.awaitTime(0.5);

            cc.tween(this.node)
                .to(0.5, {y: cc.winSize.height})
                .start();

            await cc.vv.gameData.awaitTime(0.5);

            this.black_bg.active = false;
            this.node.active = false;
        } else if (msg.data.rtype === 3) {
            cc.find("wheel", this.node.parent).getComponent("FatherOfInvention_Wheel").onRcvSubGameData(msg);
        }
    },
});